import { useId, type ReactNode } from "react";
import { cn } from "@/lib/utils";

type MarkProps = { className?: string; label?: boolean };

function Frame({
  className,
  title,
  label = true,
  children,
}: MarkProps & { title: string; children: ReactNode }) {
  return (
    <span className={cn("inline-flex items-center gap-2 text-ink-soft", className)} title={title}>
      {children}
      {label ? <span className="text-sm font-semibold tracking-tight text-ink">{title}</span> : null}
    </span>
  );
}

function Icon({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <svg viewBox="0 0 24 24" className={cn("size-5 shrink-0", className)} aria-hidden="true">
      {children}
    </svg>
  );
}

